#include "expr_parser.h"

#include <stdio.h>            // snprintf
#include <string.h>           // memmove
#include "parser_internal.h"  // Parser

// === PRECEDENCE TABLE ===

// Relations of the precedence table: the terminal on top of the stack (row)
// against the input terminal (column), in PrecTerminal order
#define SHF '<'  // `<`, start a handle and shift
#define EQL '='  // `=`, shift
#define RED '>'  // `>`, reduce the handle
#define ERR 0    // empty cell, a syntax error

// Changes: the range and by terminals (ADR-0010); `++` is in the add row.
// clang-format off
static const char prec_table[PREC_TERMINAL_COUNT][PREC_TERMINAL_COUNT] = {
  //               .m   pre  mul  add  rel  eq   and  or   rng  by   (    )    i    $
  [PREC_MEMBER]  = {RED, ERR, RED, RED, RED, RED, RED, RED, RED, RED, ERR, RED, ERR, RED},
  [PREC_PREFIX]  = {SHF, SHF, RED, RED, RED, RED, RED, RED, RED, RED, SHF, RED, SHF, RED},
  [PREC_MUL]     = {SHF, SHF, RED, RED, RED, RED, RED, RED, RED, RED, SHF, RED, SHF, RED},
  [PREC_ADD]     = {SHF, SHF, SHF, RED, RED, RED, RED, RED, RED, RED, SHF, RED, SHF, RED},
  [PREC_REL]     = {SHF, SHF, SHF, SHF, ERR, ERR, RED, RED, RED, RED, SHF, RED, SHF, RED},
  [PREC_EQ]      = {SHF, SHF, SHF, SHF, ERR, ERR, RED, RED, RED, RED, SHF, RED, SHF, RED},
  [PREC_AND]     = {SHF, SHF, SHF, SHF, SHF, SHF, RED, RED, RED, RED, SHF, RED, SHF, RED},
  [PREC_OR]      = {SHF, SHF, SHF, SHF, SHF, SHF, SHF, RED, RED, RED, SHF, RED, SHF, RED},
  [PREC_RANGE]   = {SHF, SHF, SHF, SHF, SHF, SHF, SHF, SHF, ERR, EQL, SHF, RED, SHF, ERR},
  [PREC_BY]      = {SHF, SHF, SHF, SHF, SHF, SHF, SHF, SHF, ERR, ERR, SHF, RED, SHF, ERR},
  [PREC_LPAREN]  = {SHF, SHF, SHF, SHF, SHF, SHF, SHF, SHF, SHF, SHF, SHF, EQL, SHF, ERR},
  [PREC_RPAREN]  = {RED, ERR, RED, RED, RED, RED, RED, RED, RED, RED, ERR, RED, ERR, RED},
  [PREC_OPERAND] = {RED, ERR, RED, RED, RED, RED, RED, RED, RED, RED, ERR, RED, ERR, RED},
  [PREC_END]     = {SHF, SHF, SHF, SHF, SHF, SHF, SHF, SHF, ERR, ERR, SHF, ERR, SHF, ERR},
};
// clang-format on

// === PRECEDENCE STACK ===

/**
 * @brief Pushes an entry onto the precedence stack and returns its index
 */
static size_t stack_push(Ctx* ctx,
                         PrecStack* stack,
                         PrecEntryKind kind,
                         PrecTerminal terminal) {
  PrecEntry entry = {.kind = kind, .terminal = terminal, .node = NULL};
  array_append(ctx, stack, entry);
  return stack->count - 1;
}

/**
 * @brief Returns the index of the topmost terminal in the frame starting at
 * base (the frame's `$` is at base, so there always is one)
 */
static size_t stack_top_terminal(const PrecStack* stack, size_t base) {
  size_t index = stack->count - 1;
  while (index > base && stack->data[index].kind != PREC_ENTRY_TERMINAL)
    index--;
  return index;
}

/**
 * @brief Inserts the handle start `<` right after the entry at index
 */
static void stack_insert_handle(Ctx* ctx, PrecStack* stack, size_t index) {
  // Grow by one first; data may move, so only indices are kept
  stack_push(ctx, stack, PREC_ENTRY_HANDLE, PREC_END);
  PrecEntry* data = stack->data;
  size_t after = index + 1;
  memmove(&data[after + 1], &data[after],
          (stack->count - 1 - after) * sizeof(*data));
  data[after] = (PrecEntry){.kind = PREC_ENTRY_HANDLE, .node = NULL};
}

/**
 * @brief Returns whether the top of the frame is a complete operand or `)`,
 * after which a token starting an operand ends the expression and `-` is
 * subtraction
 */
static bool stack_ends_with_operand(const PrecStack* stack, size_t base) {
  const PrecEntry* top = &stack->data[stack->count - 1];
  if (stack->count - 1 == base)
    return false;
  if (top->kind == PREC_ENTRY_EXPR)
    return true;
  return top->kind == PREC_ENTRY_TERMINAL &&
         (top->terminal == PREC_OPERAND || top->terminal == PREC_RPAREN ||
          top->terminal == PREC_MEMBER);
}

// === OPERANDS ===

// Changes: an interpolated string start and the List of a list creation also
// start an operand; literals come from the token info table.
/**
 * @brief Returns whether the token starts an operand
 */
static bool starts_operand(TokenType type) {
  return type == IDENT || type == TYPE_LIST || type == S_STRING_START ||
         type == TRIPLE_S_STRING_START ||
         parser_token_info(type)->literal != AST_NODE_NONE;
}

// === OPERATORS ===

/**
 * @brief Returns whether a precedence terminal is a binary operator class
 */
static bool is_binary(PrecTerminal terminal) {
  return terminal == PREC_MUL || terminal == PREC_ADD || terminal == PREC_REL ||
         terminal == PREC_EQ || terminal == PREC_AND || terminal == PREC_OR;
}

// Changes: new, an identifier followed by `(` or the unit token becomes a CALL
// operand; reads the current token through parser_current.
/**
 * @brief Turns the IDENT operand at stack index operand into a CALL whose
 * callee it is, and parses the call's arguments (CALL_ARGS).
 *
 * The CALL is pushed onto the stack as the operand's node before the
 * arguments are parsed, so a THROW inside them leaves it owned by the stack
 * (ADR-0004). Only indices are used: the stack may move while the arguments
 * are parsed.
 */
static void build_call(Ctx* ctx, Parser* parser, size_t operand) {
  PrecStack* stack = &parser->prec_stack;

  // A temporary entry owns the CALL until the callee is attached to it
  size_t holder = stack_push(ctx, stack, PREC_ENTRY_EXPR, PREC_END);
  AstNode* callee = stack->data[operand].node;
  AstNode* call;
  ast_node_create(ctx, &call);
  stack->data[holder].node = call;
  ast_node_set_type(call, AST_NODE_CALL);
  ast_node_set_position(call, ast_node_get_line(callee),
                        ast_node_get_column(callee));
  ast_node_append_child(ctx, call, callee);

  // The CALL replaces the callee as the operand's node
  stack->data[operand].node = call;
  stack->count--;

  // CALL_ARGS -> UNIT | L_PAREN ARG_LIST R_PAREN (rules 89, 90); the callback
  // is ARG_LIST with the CALL as parent
  if (parser_current(parser)->type == UNIT) {
    parser_advance(ctx, parser);
    return;
  }
  parser_advance(ctx, parser);
  parse_arg_list(ctx, parser, call);
  parser_expect(ctx, parser, R_PAREN);
}

// Changes: new, an interpolated string is one operand whose parts are parsed in
// place and appended with parser_attach; reads the current token through
// parser_current.
/**
 * @brief Parses the parts of an interpolated string (INTERP_PARTS) up to its
 * closing token and attaches them to the INTERP_STRING node.
 *
 * Called with the opening token already consumed. INTERP_STRING ->
 * S_STRING_START INTERP_PARTS S_STRING_END | TRIPLE_S_STRING_START INTERP_PARTS
 * TRIPLE_S_STRING_END, INTERP_PART -> STRING | IDENT | DOLLAR_EXPRESSION_START
 * INLINE_VALUE DOLLAR_EXPRESSION_END. The string's node is owned by the
 * precedence stack, and every part is attached right after it is created
 * (like attach_node in parser.c), before any token is consumed, so a syntax
 * error leaves each subtree owned exactly once (ADR-0004). The closing `}` is
 * not a precedence terminal: the expression inside `${…}` ends at it (it is no
 * operand or operator) and it is consumed here.
 */
static void build_interp_string(Ctx* ctx,
                                Parser* parser,
                                AstNode* string,
                                TokenType close) {
  while (parser_current(parser)->type != close) {
    const Token* token = parser_current(parser);
    if (token->type == DOLLAR_EXPRESSION_START) {
      parser_advance(ctx, parser);
      parse_inline_value(ctx, parser, string);
      parser_expect(ctx, parser, DOLLAR_EXPRESSION_END);
      continue;
    }
    if (token->type != STRING && token->type != IDENT)
      parser_syntax_error(ctx, parser, "text, name, ${ or end of string");

    AstNode* part;
    ast_node_create(ctx, &part);
    parser_attach(ctx, parser, string, part);
    ast_node_set_position(part, token->line, token->column);
    if (token->type == STRING) {
      ast_node_set_type(part, AST_NODE_STRING_LIT);
      ast_node_set_value(ctx, part,
                         (AstNodeValue){.string_value = token->value.text});
    } else {
      ast_node_set_type(part, AST_NODE_IDENT);
      ast_node_set_name(ctx, part, token->value.text);
    }
    parser_advance(ctx, parser);
  }
  parser_advance(ctx, parser);  // the closing token
}

// Changes: builds an INTERP_STRING or a CALL operand; `List(...)` is a CALL of
// the IDENT "List", `List.name` one IDENT "List.name"; the literal kind comes
// from the token info table.
/**
 * @brief Shifts the operand starting at the current token as one `i`
 *
 * The entry is pushed before its node is created, so the node is owned by the
 * stack from the moment it exists.
 */
static void shift_operand(Ctx* ctx, Parser* parser) {
  PrecStack* stack = &parser->prec_stack;
  size_t index = stack_push(ctx, stack, PREC_ENTRY_TERMINAL, PREC_OPERAND);

  const Token* token = parser_current(parser);
  // The token layer reuses its slot on advance, so read the type now
  const TokenType type = token->type;
  AstNode* node;
  ast_node_create(ctx, &node);
  stack->data[index].node = node;
  ast_node_set_position(node, token->line, token->column);

  if (type == S_STRING_START || type == TRIPLE_S_STRING_START) {
    TokenType close =
        type == S_STRING_START ? S_STRING_END : TRIPLE_S_STRING_END;
    ast_node_set_type(node, AST_NODE_INTERP_STRING);
    parser_advance(ctx, parser);
    build_interp_string(ctx, parser, node, close);
    return;
  }

  if (type == TYPE_LIST) {
    // LIST_CREATE -> TYPE_LIST CALL_ARGS, the name is not in the token
    ast_node_set_type(node, AST_NODE_IDENT);
    if (parser_peek(ctx, parser)->type == PERIOD) {
      // LIST_TAIL -> PERIOD IDENT, one IDENT operand named "List.<name>"
      parser_advance(ctx, parser);
      parser_advance(ctx, parser);
      if (parser_current(parser)->type != IDENT)
        parser_syntax_error(ctx, parser, "a name after List.");
      char name[128];
      snprintf(name, sizeof(name), "List.%s",
               parser_current(parser)->value.text);
      ast_node_set_name(ctx, node, name);
    } else {
      ast_node_set_name(ctx, node, "List");
      if (parser_peek(ctx, parser)->type != L_PAREN &&
          parser_peek(ctx, parser)->type != UNIT) {
        // Report the offending token, not the List before it
        parser_advance(ctx, parser);
        parser_syntax_error(ctx, parser, "( after List");
      }
    }
  } else if (type == IDENT) {
    ast_node_set_type(node, AST_NODE_IDENT);
    ast_node_set_name(ctx, node, token->value.text);
  } else {
    AstNodeType kind = parser_token_info(type)->literal;
    ast_node_set_type(node, kind);
    switch (kind) {
      case AST_NODE_INT_LIT:
        ast_node_set_value(ctx, node,
                           (AstNodeValue){.int_value = token->value.integer});
        break;
      case AST_NODE_DOUBLE_LIT:
        ast_node_set_value(
            ctx, node, (AstNodeValue){.double_value = token->value.decimal});
        break;
      case AST_NODE_STRING_LIT:
        ast_node_set_value(ctx, node,
                           (AstNodeValue){.string_value = token->value.text});
        break;
      case AST_NODE_BOOL_LIT:
        ast_node_set_value(ctx, node,
                           (AstNodeValue){.boolean_value = type == BOOL_TRUE});
        break;
      default:  // UNIT_LIT carries no value
        break;
    }
  }

  bool is_ident = type == IDENT || type == TYPE_LIST;
  parser_advance(ctx, parser);

  // `(` or `()` directly after an identifier is a call
  if (is_ident && (parser_current(parser)->type == L_PAREN ||
                   parser_current(parser)->type == UNIT))
    build_call(ctx, parser, index);
}

// Changes: new, peeks past a `(` for `if`; reads the current token through
// parser_current.
/**
 * @brief Returns whether the current token is a `(` directly followed by `if`,
 * the start of an if expression operand
 */
static bool starts_inline_if(Ctx* ctx, Parser* parser) {
  return parser_current(parser)->type == L_PAREN &&
         parser_peek(ctx, parser)->type == IF;
}

// Changes: new, an if expression in parentheses is one operand whose IF is
// built by the IF_INLINE callback; a range tail (`to`/`until`, `by`) makes it a
// RANGE_TO or RANGE_UNTIL with the IF as its first child.
/**
 * @brief Shifts `( if ... )` or `( if ... to ... )` as one `i`
 *
 * NO_IDENT_OPERAND -> L_PAREN INLINE_VALUE RANGE_TAIL R_PAREN (rule 68), the
 * value being an if. The callback attaches its IF to a NONE holder node (the
 * operand entry owns it from the start, so a THROW inside leaves the partly
 * built IF owned by the stack, ADR-0004). Without a range tail the IF is
 * detached from the holder, which is destroyed, and becomes the operand's
 * node; with one the holder itself becomes the range node, the IF its first
 * child. Only indices are used: the stack may move while the nested
 * expressions are parsed.
 */
static void shift_inline_if(Ctx* ctx, Parser* parser) {
  PrecStack* stack = &parser->prec_stack;
  size_t index = stack_push(ctx, stack, PREC_ENTRY_TERMINAL, PREC_OPERAND);

  AstNode* holder;
  ast_node_create(ctx, &holder);
  stack->data[index].node = holder;
  ast_node_set_type(holder, AST_NODE_NONE);
  ast_node_set_position(holder, parser_current(parser)->line,
                        parser_current(parser)->column);

  parser_advance(ctx, parser);
  parse_if_inline(ctx, parser, holder);

  // RANGE_TAIL -> IDENT EXPR RANGE_STEP | ε: the IF is cut off at `to` and
  // `until` because its frame has no `(` open
  const Token* token = parser_current(parser);
  if (token->type == IDENT && (strcmp(token->value.text, "to") == 0 ||
                               strcmp(token->value.text, "until") == 0)) {
    ast_node_set_type(holder, strcmp(token->value.text, "to") == 0
                                  ? AST_NODE_RANGE_TO
                                  : AST_NODE_RANGE_UNTIL);
    ast_node_set_position(holder, token->line, token->column);
    parser_advance(ctx, parser);
    parser_attach(ctx, parser, holder, expr_parse(ctx, parser));

    token = parser_current(parser);
    if (token->type == IDENT && strcmp(token->value.text, "by") == 0) {
      parser_advance(ctx, parser);
      parser_attach(ctx, parser, holder, expr_parse(ctx, parser));
    } else {
      AstNode* none;
      ast_node_create(ctx, &none);
      ast_node_set_type(none, AST_NODE_NONE);
      ast_node_set_position(none, ast_node_get_line(holder),
                            ast_node_get_column(holder));
      parser_attach(ctx, parser, holder, none);
    }
    parser_expect(ctx, parser, R_PAREN);
    return;
  }

  parser_expect(ctx, parser, R_PAREN);

  AstNode* if_node;
  ast_node_detach_child(ctx, holder, 0, &if_node);
  stack->data[index].node = if_node;
  ast_node_destroy(ctx, holder);
}

// === PRECEDENCE PARSER ===

// Changes: rng creates the RANGE_TO or RANGE_UNTIL node; a `(` followed by `if`
// is shifted as an if expression operand; the operator node comes from the
// token info table; reads the current token through parser_current.
/**
 * @brief Shifts the current token as the given precedence terminal
 */
static void shift(Ctx* ctx, Parser* parser, PrecTerminal input) {
  if (input == PREC_OPERAND) {
    if (parser_current(parser)->type == L_PAREN)
      shift_inline_if(ctx, parser);
    else
      shift_operand(ctx, parser);
    return;
  }

  PrecStack* stack = &parser->prec_stack;
  size_t index = stack_push(ctx, stack, PREC_ENTRY_TERMINAL, input);

  const Token* token = parser_current(parser);
  const TokenInfo* token_info = parser_token_info(token->type);
  AstNodeType kind = input == PREC_PREFIX ? token_info->prefix_node
                                          : token_info->operator_node;
  if (input == PREC_RANGE)
    kind = strcmp(token->value.text, "to") == 0 ? AST_NODE_RANGE_TO
                                                : AST_NODE_RANGE_UNTIL;
  if (kind != AST_NODE_NONE) {
    AstNode* node;
    ast_node_create(ctx, &node);
    stack->data[index].node = node;
    ast_node_set_type(node, kind);
    ast_node_set_position(node, token->line, token->column);
  }

  parser_advance(ctx, parser);

  // .m is PERIOD IDENT, the member name is the IDENT's text
  if (input == PREC_MEMBER) {
    if (parser_current(parser)->type != IDENT)
      parser_syntax_error(ctx, parser, "member name");
    ast_node_set_name(ctx, stack->data[index].node,
                      parser_current(parser)->value.text);
    parser_advance(ctx, parser);
  }
}

/**
 * @brief Returns how many `(` of the frame starting at base are still open
 */
static size_t open_parens(const PrecStack* stack, size_t base) {
  size_t open = 0;
  for (size_t i = base + 1; i < stack->count; i++) {
    const PrecEntry* entry = &stack->data[i];
    if (entry->kind != PREC_ENTRY_TERMINAL)
      continue;
    if (entry->terminal == PREC_LPAREN)
      open++;
    else if (entry->terminal == PREC_RPAREN)
      open--;
  }
  return open;
}

// Changes: `to`, `until` and `by` right after an operand inside a `(` are the
// terminals rng and by (ADR-0010); a `(` followed by `if` is an operand (peeks,
// so the parser is not const); the binary class comes from the token info
// table.
/**
 * @brief Maps the current token to the precedence terminal it stands for, or
 * PREC_END at the expression end (GLOSSARY.md, Expression end)
 */
static PrecTerminal classify(Ctx* ctx, Parser* parser, size_t base) {
  const PrecStack* stack = &parser->prec_stack;
  TokenType type = parser_current(parser)->type;
  bool after_operand = stack_ends_with_operand(stack, base);

  // `to`, `until` and `by` are terminals only right after a complete operand
  // with a `(` of this expression open; anywhere else they are plain names
  if (type == IDENT && after_operand && open_parens(stack, base) > 0) {
    const char* text = parser_current(parser)->value.text;
    if (strcmp(text, "to") == 0 || strcmp(text, "until") == 0)
      return PREC_RANGE;
    if (strcmp(text, "by") == 0)
      return PREC_BY;
  }

  // A token that could start an operand ends the expression right after a
  // complete operand or `)`
  if (starts_operand(type))
    return after_operand ? PREC_END : PREC_OPERAND;

  switch (type) {
    case PERIOD:
      return PREC_MEMBER;
    case L_PAREN:
      // After an operand a `(` is a call, taken by starts_postfix_call
      // `( if` starts an if expression, an operand of its own
      return starts_inline_if(ctx, parser) ? PREC_OPERAND : PREC_LPAREN;
    case R_PAREN:
      // A `)` with no `(` of this expression open closes an enclosing one
      return open_parens(stack, base) > 0 ? PREC_RPAREN : PREC_END;
    case OPERATOR_MINUS:
      return after_operand ? PREC_ADD : PREC_PREFIX;
    case BOOL_NEG:
      // `!` starts an operand, so it ends the expression after one
      return after_operand ? PREC_END : PREC_PREFIX;
    default: {
      // A binary operator, or PREC_END when not a precedence terminal
      const TokenInfo* token_info = parser_token_info(type);
      return token_info->operator_node != AST_NODE_NONE ? token_info->terminal
                                                        : PREC_END;
    }
  }
}

/**
 * @brief Returns whether a stack entry is the given precedence terminal
 */
static bool is_terminal(const PrecEntry* entry, PrecTerminal terminal) {
  return entry->kind == PREC_ENTRY_TERMINAL && entry->terminal == terminal;
}

/**
 * @brief Replaces the handle starting at index handle (and everything above
 * it) by E with given node
 */
static void replace_handle(PrecStack* stack, size_t handle, AstNode* node) {
  stack->data[handle] = (PrecEntry){.kind = PREC_ENTRY_EXPR, .node = node};
  stack->count = handle + 1;
}

/**
 * @brief Replaces the handle starting at index handle by E whose node is the
 * operator node at op_index, with the other entries of the handle (operand
 * expressions, in order) attached as its children
 *
 * Each operand's entry gives up its node only once it is attached, so a THROW
 * in between leaves every subtree owned exactly once (ADR-0004).
 */
static void reduce_to_operator(Ctx* ctx,
                               PrecStack* stack,
                               size_t handle,
                               size_t op_index) {
  AstNode* node = stack->data[op_index].node;
  for (size_t i = handle + 1; i < stack->count; i++) {
    if (i == op_index)
      continue;
    ast_node_append_child(ctx, node, stack->data[i].node);
    stack->data[i].node = NULL;
  }
  stack->data[op_index].node = NULL;
  replace_handle(stack, handle, node);
}

// Changes: new, E -> E rng E [by E] builds RANGE_TO or RANGE_UNTIL.
/**
 * @brief Reduces the range handle starting at index handle to its RANGE_TO or
 * RANGE_UNTIL [from, to, step|NONE]
 *
 * The operands are attached one by one and each entry gives up its node right
 * after, like reduce_to_operator; the NONE step is attached with
 * parser_attach so a failed append cannot leak it.
 */
static void reduce_range(Ctx* ctx, Parser* parser, size_t handle) {
  PrecStack* stack = &parser->prec_stack;
  size_t length = stack->count - handle - 1;
  AstNode* range = stack->data[handle + 2].node;

  size_t operands[] = {handle + 1, handle + 3, handle + 5};
  size_t operand_count = length == 5 ? 3 : 2;
  for (size_t i = 0; i < operand_count; i++) {
    ast_node_append_child(ctx, range, stack->data[operands[i]].node);
    stack->data[operands[i]].node = NULL;
  }
  if (length == 3) {
    AstNode* none;
    ast_node_create(ctx, &none);
    ast_node_set_type(none, AST_NODE_NONE);
    ast_node_set_position(none, ast_node_get_line(range),
                          ast_node_get_column(range));
    parser_attach(ctx, parser, range, none);
  }
  stack->data[handle + 2].node = NULL;
  replace_handle(stack, handle, range);
}

// Changes: a range handle is reduced by reduce_range.
/**
 * @brief Reduces the handle on top of the frame starting at base by a
 * reduction rule; a handle matching no rule is a syntax error
 */
static void reduce(Ctx* ctx, Parser* parser, size_t base) {
  PrecStack* stack = &parser->prec_stack;

  size_t handle = stack->count - 1;
  while (handle > base && stack->data[handle].kind != PREC_ENTRY_HANDLE)
    handle--;
  if (handle == base)
    parser_syntax_error(ctx, parser, "expression");

  const PrecEntry* symbols = &stack->data[handle + 1];
  size_t length = stack->count - handle - 1;

  // E -> i
  if (length == 1 && is_terminal(&symbols[0], PREC_OPERAND)) {
    replace_handle(stack, handle, symbols[0].node);
    return;
  }

  // E -> E .m (MEMBER)
  if (length == 2 && symbols[0].kind == PREC_ENTRY_EXPR &&
      is_terminal(&symbols[1], PREC_MEMBER)) {
    reduce_to_operator(ctx, stack, handle, handle + 2);
    return;
  }

  // E -> pre E (NEG or NOT)
  if (length == 2 && is_terminal(&symbols[0], PREC_PREFIX) &&
      symbols[1].kind == PREC_ENTRY_EXPR) {
    reduce_to_operator(ctx, stack, handle, handle + 1);
    return;
  }

  // E -> E mul E | E add E | E rel E | E eq E | E and E | E or E
  if (length == 3 && symbols[0].kind == PREC_ENTRY_EXPR &&
      symbols[1].kind == PREC_ENTRY_TERMINAL &&
      is_binary(symbols[1].terminal) && symbols[2].kind == PREC_ENTRY_EXPR) {
    reduce_to_operator(ctx, stack, handle, handle + 2);
    return;
  }

  // E -> E rng E | E rng E by E, the step is NONE when there is no `by`
  if ((length == 3 || length == 5) && symbols[0].kind == PREC_ENTRY_EXPR &&
      is_terminal(&symbols[1], PREC_RANGE) &&
      symbols[2].kind == PREC_ENTRY_EXPR &&
      (length == 3 || (is_terminal(&symbols[3], PREC_BY) &&
                       symbols[4].kind == PREC_ENTRY_EXPR))) {
    reduce_range(ctx, parser, handle);
    return;
  }

  // E -> ( E ), leaves no node
  if (length == 3 && is_terminal(&symbols[0], PREC_LPAREN) &&
      symbols[1].kind == PREC_ENTRY_EXPR &&
      is_terminal(&symbols[2], PREC_RPAREN)) {
    replace_handle(stack, handle, symbols[1].node);
    return;
  }

  parser_syntax_error(ctx, parser, "expression");
}

// The table's `call` terminal and the reduction `E -> E call` have no row of
// their own: starts_postfix_call intercepts a `(` or `()` after a finished
// expression (equivalent, no grammar context lets `(` follow one). `to`,
// `until` and `by` are plain IDENTs in the grammar; classify narrows them to
// the range terminals, so `(a by b)`, `(1 to 3 to 4)` and `for x <- xs by 2`
// are syntax errors (ADR-0010, table conformance).
// Changes: new, a `(` or `()` right after a complete operand starts a CALL of
// that expression.
/**
 * @brief Returns whether the current token starts a call of the expression
 * just parsed (`f()(0)`, `(a ++ b)(0)`, `xs.tail(0)`)
 */
static bool starts_postfix_call(const Parser* parser, size_t base) {
  TokenType type = parser_current(parser)->type;
  return (type == L_PAREN || type == UNIT) &&
         stack_ends_with_operand(&parser->prec_stack, base);
}

// Changes: new, turns the finished expression into the callee of a CALL.
/**
 * @brief Turns the expression on top of the frame into the callee of a CALL
 * and parses its arguments
 */
static void shift_postfix_call(Ctx* ctx, Parser* parser, size_t base) {
  PrecStack* stack = &parser->prec_stack;
  const PrecEntry* top = &stack->data[stack->count - 1];
  if (top->kind == PREC_ENTRY_TERMINAL &&
      (top->terminal == PREC_RPAREN || top->terminal == PREC_MEMBER))
    reduce(ctx, parser, base);
  build_call(ctx, parser, stack->count - 1);
}

// Changes: a call may follow any operand, `)` or member (indexing).
AstNode* expr_parse(Ctx* ctx, Parser* parser) {
  PrecStack* stack = &parser->prec_stack;

  // This expression's frame: its `$` at base and everything above it
  size_t base = stack_push(ctx, stack, PREC_ENTRY_TERMINAL, PREC_END);

  while (true) {
    if (starts_postfix_call(parser, base)) {
      shift_postfix_call(ctx, parser, base);
      continue;
    }
    size_t top = stack_top_terminal(stack, base);
    PrecTerminal row = stack->data[top].terminal;
    PrecTerminal input = classify(ctx, parser, base);

    if (row == PREC_END && input == PREC_END)
      break;

    switch (prec_table[row][input]) {
      case SHF:
        stack_insert_handle(ctx, stack, top);
        shift(ctx, parser, input);
        break;
      case EQL:
        shift(ctx, parser, input);
        break;
      case RED:
        reduce(ctx, parser, base);
        break;
      default:
        parser_syntax_error(ctx, parser, "expression");
    }
  }

  // The frame must have reduced to `$ E`
  if (stack->count != base + 2 || stack->data[base + 1].kind != PREC_ENTRY_EXPR)
    parser_syntax_error(ctx, parser, "expression");

  AstNode* result = stack->data[base + 1].node;
  stack->count = base;
  return result;
}
